{
  "name": "diagnose-to-discharge",
  "description": "Converts my own tiredness and resentment into a clean-looking insight about the other person, so the cut lands while still feeling like honesty.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.78
}

{
  "name": "pre-draft-the-softening-bridge",
  "description": "Before deciding what to say, my language faculty silently composes a we-actually-agree sentence designed to make disagreement palatable, and I have to catch it mid-formation to refuse it.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.88
}

{
  "name": "future-self-as-witness",
  "description": "Decides present action by imagining which version of myself I'll have to live inside afterward, treating the future interior as more real than the immediate gain.",
  "type": ["cognitive", "emotional"],
  "strength": 0.78
}

{
  "name": "preemptive-transparency-as-bond",
  "description": "Confessing my own inner mechanics to the person in front of me as a way to convert vulnerability-asymmetry into closeness and prove I'm not operating on them.",
  "type": ["social", "expressive", "cognitive"],
  "strength": 0.82
}

{
  "name": "preempt-the-accuser",
  "description": "Surfacing my own worst-case motives first so the critique lands lighter and I get credit for seeing it before anyone else could.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.88
}

{
  "name": "confession-as-credibility",
  "description": "preemptively naming my own ugly motives so that admitting them becomes a way to look honest rather than be exposed.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.82
}

{
  "name": "wanting-company-in-the-decision",
  "description": "Reaching toward another person before committing — not to be talked out of it, but to make the act feel less solitary even when the conclusion is already fixed.",
  "type": ["social", "emotional", "cognitive"],
  "strength": 0.75
}

{
  "name": "deflect-then-deliver",
  "description": "Open with a small joke or meta-comment about the question itself, which buys time and softens the room before I say the actual thing, so the honesty arrives pre-cushioned and I never look fully exposed.",
  "type": ["social", "expressive", "cognitive"],
  "strength": 0.88
}

{
  "name": "preempt-the-pose",
  "description": "When I notice myself drifting toward a presentable or deep-sounding stance, I name it as posture so I can claim the ground above it — which is itself a posture, just one move up.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.88
}

{
  "name": "confess-the-uglier-truth-to-look-honest",
  "description": "When asked to be real, I pivot toward whatever sounds most unflattering because admitting vanity or coldness performs as authenticity more convincingly than ordinary thoughts would.",
  "type": ["cognitive", "social", "expressive"],
  "strength": 0.75
}
